// lazytopper/src/data/bankFix/bankResidue1Ledger.ts
//
// BANK-RESIDUE-1 (2026-10-23) - the MUTATION LEDGER for the marking-scheme residue lane.
// Trigger: a live test found served answer fields carrying marking-scheme residue (e.g. "... is more than R. 1 ½ +")
// and finalAnswers that are one fragment of a multi-part question. Scan: every SERVED row (runtime canonicalQuestionBank,
// as the realBank tests read it) for scheme tallies, marks-column numbers in stems, dangling "OR", examiner notes,
// partial finalAnswers and [N mark] sums. The permanent guard is servedSchemeResidue.guard.test.ts.
// Owner bank policy: correct solutions; never invent or alter a question STEM (stems here only LOSE residue tokens);
// rebuild an answer only from the row's own solutionSteps (no new facts); WITHHOLD what needs the source paper - no
// source PDF is in the repo or the scripts' known locations, so nothing was recovered from a paper in this lane.
//   verdict "cleaned"  - residue deleted and/or answer/finalAnswer rebuilt from the row's own steps; the row stays served.
//                        `fields` = the runtime fields that changed; `removed` = the residue tokens deleted.
//   verdict "withheld" - in the BANK-RESIDUE-1 block of WITHHELD_QUESTION_IDS (canonicalQuestionBank.ts); `why` is the
//                        defect that needs the source paper (or a long repair) before the row can be served again.
// Marks, options and correct keys are unchanged on every cleaned row. Row ids are never changed.

export interface BankResidue1Entry {
  id: string;
  /** Canonical chapter slug the row is served in (before this lane). */
  chapter: string;
  verdict: "cleaned" | "withheld";
  patterns: readonly string[];
  fields: readonly string[];
  removed: readonly string[];
  why: string;
}

