/** Ids this lane withheld; each is in the BANK-RESIDUE-1 block of WITHHELD_QUESTION_IDS. */
export const BANK_RESIDUE_1_WITHHELD_IDS: ReadonlySet<string> = new Set(
  BANK_RESIDUE_1_LEDGER.filter((e) => e.verdict === "withheld").map((e) => e.id),
);

/**
 * The template category of every row this lane withheld, in the vocabulary the GEN-THIN-1 template guard reads
 * (ltGenerated.guard.test.ts): "garbled" - the damage is extraction residue in the TEXT and the question content stays in
 * the 2026-27 syllabus, so a generated row shaped from one of these (its question type, not its damaged text) is judged
 * as the GARBLE-1 withholds are. Each id leaves this map in the PR that serves it again.
 */
export const BANK_RESIDUE_1_WITHHOLD_CATEGORY: ReadonlyMap<string, "garbled"> = new Map(
  [...BANK_RESIDUE_1_WITHHELD_IDS].map((id) => [id, "garbled"] as const),
);
